import { computed, defineComponent, h, inject, provide, ref, useId, type ComputedRef, type InjectionKey, type PropType } from 'vue';
import { accordionStyleKeys, getAccordionState, getAccordionNextValues } from '../lib/core';
import type { AccordionType } from '../lib/core';
import styles from './accordion.module.scss';

interface AccordionContextValue {
	type: AccordionType;
	collapsible: boolean;
	value: string | string[];
	toggleItem: (value: string) => void;
}

type AccordionContext = ComputedRef<AccordionContextValue>;

const AccordionContextKey: InjectionKey<AccordionContext> = Symbol('tile-accordion');

interface AccordionItemContextValue {
	value: string;
	open: boolean;
	disabled: boolean;
	contentId: string;
}

type AccordionItemContext = ComputedRef<AccordionItemContextValue>;

const AccordionItemContextKey: InjectionKey<AccordionItemContext> = Symbol('tile-accordion-item');

export const Accordion = defineComponent({
	name: 'Accordion',
	props: {
		modelValue: {
			type: [String, Array] as PropType<string | string[]>,
			default: undefined,
		},
		defaultValue: {
			type: [String, Array] as PropType<string | string[]>,
			default: undefined,
		},
		type: {
			type: String as PropType<AccordionType>,
			default: 'single',
		},
		collapsible: { type: Boolean, default: false },
	},
	emits: ['update:modelValue', 'change'],
	setup(props, { emit, slots }) {
		const internalValue = ref<string | string[]>(
			props.modelValue !== undefined ? props.modelValue : props.defaultValue !== undefined ? props.defaultValue : props.type === 'multiple' ? [] : '',
		);
		const currentValue = computed<string | string[]>(() => (props.modelValue !== undefined ? props.modelValue : internalValue.value));
		const normalized = computed<string | string[]>(() =>
			props.type === 'multiple' ? (Array.isArray(currentValue.value) ? currentValue.value : []) : typeof currentValue.value === 'string' ? currentValue.value : '',
		);

		function toggleItem(itemValue: string) {
			let next: string | string[];

			if (props.type === 'multiple') {
				const list = Array.isArray(normalized.value) ? normalized.value : [];
				next = getAccordionNextValues(itemValue, list);
			} else if (normalized.value === itemValue) {
				next = props.collapsible ? '' : normalized.value;
			} else {
				next = itemValue;
			}

			if (props.modelValue === undefined) {
				internalValue.value = next;
			}

			emit('update:modelValue', next);
			emit('change', next);
		}

		const context = computed<AccordionContextValue>(() => ({
			type: props.type,
			collapsible: props.collapsible,
			value: normalized.value,
			toggleItem,
		}));

		provide(AccordionContextKey, context);

		return () => h('div', { 'data-slot': 'accordion', class: styles[accordionStyleKeys.root] }, slots.default?.());
	},
});

export const AccordionItem = defineComponent({
	name: 'AccordionItem',
	props: {
		value: { type: String, required: true },
		disabled: { type: Boolean, default: false },
	},
	setup(props, { slots }) {
		const accordion = inject(AccordionContextKey);
		if (!accordion) {
			throw new Error('AccordionItem must be used within <Accordion>.');
		}

		const open = computed(() =>
			accordion.value.type === 'multiple' ? Array.isArray(accordion.value.value) && accordion.value.value.includes(props.value) : accordion.value.value === props.value,
		);

		const contentId = `tile-accordion-${useId()}`;

		const itemContext = computed<AccordionItemContextValue>(() => ({
			value: props.value,
			open: open.value,
			disabled: props.disabled,
			contentId,
		}));

		provide(AccordionItemContextKey, itemContext);

		return () => h('div', { class: styles[accordionStyleKeys.item], 'data-state': getAccordionState(open.value) }, slots.default?.());
	},
});

export const AccordionTrigger = defineComponent({
	name: 'AccordionTrigger',
	setup(_props, { slots }) {
		const accordion = inject(AccordionContextKey);
		if (!accordion) {
			throw new Error('AccordionTrigger must be used within <Accordion>.');
		}

		const item = inject(AccordionItemContextKey);
		if (!item) {
			throw new Error('AccordionTrigger must be used within <AccordionItem>.');
		}

		function handleKeydown(event: KeyboardEvent) {
			const keys = ['ArrowDown', 'ArrowUp', 'Home', 'End'];
			if (!keys.includes(event.key)) {
				return;
			}

			const root = (event.currentTarget as HTMLElement).closest('[data-slot="accordion"]');
			if (!root) {
				return;
			}
			const triggers = Array.from(root.querySelectorAll<HTMLButtonElement>('button[aria-expanded]')).filter((button) => !button.disabled);
			if (triggers.length === 0) {
				return;
			}

			const index = triggers.indexOf(event.currentTarget as HTMLButtonElement);
			let next = index;
			if (event.key === 'ArrowDown') {
				next = (index + 1) % triggers.length;
			} else if (event.key === 'ArrowUp') {
				next = (index - 1 + triggers.length) % triggers.length;
			} else if (event.key === 'Home') {
				next = 0;
			} else if (event.key === 'End') {
				next = triggers.length - 1;
			}

			event.preventDefault();
			triggers[next]?.focus();
		}

		return () =>
			h('div', { class: styles[accordionStyleKeys.header] }, [
				h(
					'button',
					{
						type: 'button',
						'aria-expanded': item.value.open,
						'aria-controls': item.value.contentId,
						'data-state': getAccordionState(item.value.open),
						disabled: item.value.disabled,
						class: styles[accordionStyleKeys.trigger],
						onClick: () => accordion.value.toggleItem(item.value.value),
						onKeydown: handleKeydown,
					},
					[
						slots.default?.(),
						h(
							'svg',
							{
								class: styles[accordionStyleKeys.chevron],
								xmlns: 'http://www.w3.org/2000/svg',
								width: '16',
								height: '16',
								viewBox: '0 0 24 24',
								fill: 'none',
								stroke: 'currentColor',
								'stroke-width': '2',
								'stroke-linecap': 'round',
								'stroke-linejoin': 'round',
							},
							[h('path', { d: 'm6 9 6 6 6-6' })],
						),
					],
				),
			]);
	},
});

export const AccordionContent = defineComponent({
	name: 'AccordionContent',
	setup(_props, { slots }) {
		const item = inject(AccordionItemContextKey);
		if (!item) {
			throw new Error('AccordionContent must be used within <AccordionItem>.');
		}

		return () =>
			h('div', { id: item.value.contentId, 'data-state': getAccordionState(item.value.open), class: styles[accordionStyleKeys.content] }, [
				h('div', { class: styles[accordionStyleKeys.contentInner] }, slots.default?.()),
			]);
	},
});

export default Accordion;

@use '../../../styles/variables/colors' as *;

.root {
	width: 100%;
}

.item {
	border-bottom: 1px solid var(--tile-accordion-border, $border);

	&:last-child {
		border-bottom: none;
	}
}

.header {
	display: flex;
}

.trigger {
	display: flex;
	flex: 1;
	align-items: center;
	justify-content: space-between;
	gap: $spacing-4;
	border-radius: var(--tile-accordion-radius, $radius-md);
	padding: var(--tile-accordion-trigger-padding, $spacing-4 0);
	text-align: left;
	font-size: var(--tile-accordion-font-size, $text-sm);
	font-weight: $font-medium;
	color: var(--tile-accordion-foreground, inherit);
	transition: all $transition-fast;
	outline: none;

	&:hover {
		text-decoration: var(--tile-accordion-hover-decoration, underline);
		background-color: var(--tile-accordion-hover-background, transparent);
	}

	&:focus-visible {
		box-shadow: var(--tile-accordion-focus-shadow, 0 0 0 2px $background, 0 0 0 4px $ring);
	}

	&:disabled {
		pointer-events: none;
		opacity: 0.5;
	}

	&[data-state='open'] .chevron {
		transform: rotate(180deg);
	}
}

.chevron {
	pointer-events: none;
	width: 1rem;
	height: 1rem;
	flex-shrink: 0;
	color: var(--tile-accordion-subtle, $muted-foreground);
	transition: transform $transition-normal;
}

.content {
	display: grid;
	grid-template-rows: 0fr;
	overflow: hidden;
	padding-bottom: 0;
	text-align: left;
	font-size: var(--tile-accordion-font-size, $text-sm);
	color: var(--tile-accordion-content-foreground, inherit);
	transition:
		grid-template-rows $transition-slow,
		padding-bottom $transition-slow;

	&[data-state='open'] {
		grid-template-rows: 1fr;
		padding-bottom: var(--tile-accordion-content-padding-bottom, $spacing-4);
	}
}

.contentInner {
	overflow: hidden;
	min-height: 0;
}

@media (prefers-reduced-motion: reduce) {
	.trigger,
	.chevron,
	.content {
		transition: none;
	}
}
